use super::*;
use crate::build::workbench::fixture::DECLARATION;

fn render(source: &str) -> String {
    TsSchema::render(&Schema::parse(source, "test/typed", "Typed").unwrap())
}

#[test]
fn a_version_1_module_has_a_schema_and_its_value_types() {
    assert_eq!(
        render(DECLARATION),
        "// Generated by patchkit from workbench.toml. Do not edit.\n\
         export const schema = {\n  module: 'test/typed',\n  version: 1,\n  settings: [\n\
         \x20   { id: 'boot', label: 'État', kind: 'text', apply: 'immediate', maxBytes: 16 },\n\
         \x20   { id: 'active', label: 'Animation', kind: 'file-name', apply: 'next-restart', maxBytes: 47, extension: 'dkbs', resetLabel: 'None' },\n\
         \x20 ],\n} as const;\n\n\
         export interface Settings {\n  boot: string | null;\n  active: string | null;\n}\n"
    );
}

#[test]
fn the_new_types_carry_their_fields_and_types() {
    let source = format!(
        "{DECLARATION}\n\
         [[setting]]\nid = \"gain\"\nlabel = \"Gain\"\ntype = \"integer\"\nmin = -10\nmax = 10\nstep = 2\ndecimals = 1\nunit = \"dB\"\ndefault = 0\n\
         [[setting]]\nid = \"mix-on\"\nlabel = \"Mix\"\ntype = \"boolean\"\ndefault = true\n\
         [[setting]]\nid = \"mode\"\nlabel = \"Mode\"\ntype = \"choice\"\nchoices = [\"Off\", \"It's\"]\ndefault = \"It's\"\n"
    );
    let text = render(&source);
    for line in [
        "  version: 2,",
        "    { id: 'gain', label: 'Gain', kind: 'integer', apply: 'immediate', min: -10, max: 10, step: 2, decimals: 1, unit: 'dB', default: 0 },",
        "    { id: 'mix-on', label: 'Mix', kind: 'boolean', apply: 'immediate', default: true },",
        "    { id: 'mode', label: 'Mode', kind: 'choice', apply: 'immediate', choices: ['Off', 'It\\'s'], default: 'It\\'s' },",
        "  gain: number;",
        "  'mix-on': boolean;",
        "  mode: 'Off' | 'It\\'s';",
    ] {
        assert!(text.contains(line), "{line}\n{text}");
    }
    assert!(!text.contains("import"));
}

#[test]
fn strings_are_escaped_for_a_single_quoted_literal() {
    assert_eq!(quote("a'b\\c\nd"), "'a\\'b\\\\c\\u000ad'");
    assert_eq!(quote("é"), "'é'");
    assert_eq!(property("ok_1"), "ok_1");
    assert_eq!(property("a-b"), "'a-b'");
    assert_eq!(property("1a"), "'1a'");
}
